function addSceneShot(){const char=continuity.get($("nsCharacter").value);if(!char)throw new Error("Selecciona un personaje de la biblia");if(!char.face||!char.eyes||!char.hair||!char.body||!char.palette||!char.outfit)throw new Error("Completa rostro, ojos, cabello, cuerpo, paleta y vestuario en la ficha maestra");scene.setTitle($("nsTitle").value);const shot=scene.addShot({name:$("nsName").value||"Plano "+(scene.data.shots.length+1),characterId:char.id,action:$("nsAction").value,dialogue:$("nsDialogue").value,location:$("nsLocation").value,camera:$("nsCamera").value,duration:$("nsDuration").value,voiceId:char.voiceId});syncSceneCompositor();renderShotList();$("nsStatus").textContent="Plano añadido. Voz vinculada a "+char.name+".";return shot}

